-- public.planter_target(p_world uuid, c creature, p_seed boolean, p_x double precision, p_y double precision)
-- Generated by scripts/snapshot-functions.mjs from the migrations. Do not edit.
CREATE OR REPLACE FUNCTION public.planter_target(p_world uuid, c creature, p_seed boolean, p_x double precision, p_y double precision)
 RETURNS placed
 LANGUAGE sql
 STABLE
AS $function$
  select p.* from placed p, my_deed(p_world, c.keeper) dd
   where dd.world_id is not null and p.world_id = p_world and p.kind = 'furniture' and is_planter(p.sub)
     and p.x between dd.x - work_range(c) and dd.x + work_range(c) and p.y between dd.y - work_range(c) and dd.y + work_range(c)
     and greatest(abs(p.x - dd.x), abs(p.y - dd.y)) <= work_range(c) and on_home_deed(p_world, c.keeper, p.x, p.y)
     and case when exists (select 1 from planter_crop pc where pc.placed = p.id)
              then exists (select 1 from planter_crop pc where pc.placed = p.id and (pc.stage >= crop_ripe() or not pc.tended_now))
              else p_seed end
   order by (p.cx - p_x) ^ 2 + (p.cy - p_y) ^ 2, p.id limit 1
$function$
